WITH a(x) AS (VALUES 1,2),b(y) AS (SELECT x+1 FROM a) SELECT x,y FROM a JOIN b ON x=y ORDER BY x;
WITH q AS (SELECT 1 AS a,2 AS b) TABLE q;
WITH q(x) AS (VALUES(1,2)) TABLE q;
WITH q(x,unused) AS (VALUES 1) TABLE q;
