WITH q AS (TABLE later),later AS (VALUES 1) TABLE q;
WITH q AS (SELECT 1 AS x,2 AS x) TABLE q;
WITH q AS (SELECT missing) VALUES 1;
SELECT (WITH q(x) AS (SELECT t.v) TABLE q) AS n FROM (VALUES 1) t(v);
SELECT (WITH q(x) AS (VALUES 1) SELECT t.v+x FROM q) AS n FROM (VALUES 1,2) t(v) ORDER BY n;
WITH q(x) AS (VALUES 1) SELECT (WITH q(y) AS (VALUES 2) TABLE q) AS n;
WITH RECURSIVE r(n) AS (VALUES 1 UNION ALL SELECT n+1 FROM r WHERE n<4) TABLE r;
SELECT SUM(n) AS total FROM (WITH RECURSIVE r(n) AS (VALUES 1 UNION ALL SELECT n+1 FROM r WHERE n<3) TABLE r);
WITH RECURSIVE r(n) AS (VALUES 1 UNION ALL SELECT n+1 FROM r WHERE n<3) SELECT a.n,b.n FROM r a JOIN r b ON a.n=b.n ORDER BY a.n;
WITH RECURSIVE r(n) AS (VALUES 1,1 UNION SELECT n+1 FROM r WHERE n<3) TABLE r;
WITH RECURSIVE r(n) AS (VALUES 1,1 EXCEPT SELECT n+1 FROM r WHERE n<3) TABLE r;
WITH RECURSIVE r(n) AS (VALUES 1,1 INTERSECT SELECT n+1 FROM r WHERE n<3) TABLE r;
WITH RECURSIVE r(n) AS (VALUES 1 UNION ALL SELECT n+1 FROM r WHERE n<3 ORDER BY 1 DESC LIMIT 1) TABLE r;
WITH RECURSIVE r(n) AS (SELECT '001' UNION ALL SELECT CAST(n AS INT)+1 FROM r WHERE CAST(n AS INT)<3) TABLE r;
WITH RECURSIVE r(n) AS (SELECT 1 WHERE FALSE UNION ALL SELECT n+1 FROM r WHERE n<3) TABLE r;
WITH RECURSIVE r AS (VALUES 1) TABLE r;
WITH r(n) AS (VALUES 1 UNION ALL SELECT n+1 FROM r WHERE n<3) TABLE r;
WITH RECURSIVE r(n) AS (SELECT n FROM r) TABLE r;
WITH RECURSIVE r(n) AS (SELECT n FROM r) VALUES 1;
WITH RECURSIVE r(n) AS (WITH RECURSIVE q(x) AS (VALUES 1) TABLE q) TABLE r;
WITH RECURSIVE r(n) AS (VALUES 1) SELECT n FROM r WHERE n IN(WITH RECURSIVE q(x) AS (VALUES 1) TABLE q);
WITH RECURSIVE r(n) AS (VALUES 1 UNION ALL SELECT n+1 FROM r WHERE n<3),s(m) AS (SELECT n FROM r) SELECT n,m FROM r JOIN s ON n=m ORDER BY n;
WITH RECURSIVE r(n) AS (WITH q(x) AS (VALUES 1) SELECT x FROM q UNION ALL SELECT n+1 FROM r WHERE n<3) TABLE r;
WITH RECURSIVE r(n) AS (VALUES 1 UNION ALL SELECT n+1 FROM r WHERE n<3),s(m) AS (VALUES 10 UNION ALL SELECT m+1 FROM s WHERE m<12) SELECT n,m FROM r JOIN s ON n=m-9 ORDER BY n;
