CREATE TABLE folder(id INT PRIMARY KEY,name VARCHAR,parent INT);
INSERT INTO folder VALUES(1,NULL,NULL),(2,'bin',1),(3,'docs',1),(4,'html',3);
WITH RECURSIVE link(id,name,level) AS (SELECT id,name,0 FROM folder WHERE parent IS NULL UNION ALL SELECT f.id,IFNULL(link.name||'/','')||f.name,level+1 FROM link JOIN folder f ON link.id=f.parent) SELECT name FROM link WHERE name IS NOT NULL ORDER BY id;
DROP TABLE folder;
CREATE TABLE t AS WITH q(x) AS (VALUES 1,2) TABLE q;
INSERT INTO t WITH RECURSIVE r(n) AS (VALUES 3 UNION ALL SELECT n+1 FROM r WHERE n<4) TABLE r;
BEGIN;
UPDATE t SET x=(WITH q(y) AS (VALUES 10) TABLE q) WHERE x=1;
DELETE FROM t WHERE x IN(WITH q(y) AS (VALUES 2) TABLE q);
ROLLBACK;
TABLE t ORDER BY x;
DROP TABLE t;
