CREATE TABLE edges(parent VARCHAR,child VARCHAR);
INSERT INTO edges VALUES('/','a'),('a','b1'),('a','b2'),('a','c'),('c','d1'),('c','d2');
WITH RECURSIVE r(depth,parent,child) AS (SELECT 0,parent,child FROM edges WHERE parent='/' UNION ALL SELECT depth+1,r.parent,r.child FROM edges i JOIN r ON i.parent=r.child WHERE depth<9) SELECT COUNT(*) AS total FROM r;
WITH RECURSIVE r(depth,parent,child) AS (SELECT 0,parent,child FROM edges WHERE parent='/' UNION ALL SELECT depth+1,i.parent,i.child FROM edges i JOIN r ON r.child=i.parent WHERE depth<10) SELECT COUNT(*) AS total FROM r;
DROP TABLE edges;
WITH RECURSIVE r(n) AS (WITH q(x) AS (SELECT n FROM r) SELECT 1 UNION ALL SELECT x+1 FROM q WHERE x<3) TABLE r;
